using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace Kentavr.SheetsToSO.Core
{
    /// <summary>
    /// Generates C# source text from header column definitions.
    /// Output uses '\n' line endings and 4-space indentation regardless of the OS.
    /// </summary>
    public static class CodeGenerator
    {
        /// <summary>Comment block placed at <see cref="CodeTemplates.HeaderPlaceholder"/>.</summary>
        public const string Header =
            "// <auto-generated>\n" +
            "// Generated by Kentavr.SheetsToSO. Do not edit manually: changes will be lost on the next generation.\n" +
            "// </auto-generated>";

        private const string MemberIndent = "        ";

        /// <summary>
        /// Generates the row class of a sheet: one public field per column, in column order.
        /// </summary>
        public static string GenerateRowClass(string className, IReadOnlyList<ColumnDefinition> columns, CodeGenOptions options)
        {
            ValidateName(className, nameof(className), "class name");
            if (columns == null)
                throw new ArgumentNullException(nameof(columns));
            if (options == null)
                throw new ArgumentNullException(nameof(options));

            var fields = new StringBuilder();
            for (var i = 0; i < columns.Count; i++)
            {
                var column = columns[i];
                if (column == null)
                    throw new ArgumentException($"Column at index {i} is null", nameof(columns));
                if (column.Name == className)
                    throw new ArgumentException(
                        $"Column '{column.Name}' has the same name as the class '{className}'", nameof(columns));

                if (fields.Length > 0)
                    fields.Append('\n');

                var type = column.Type;
                if (type.Kind == ColumnKind.Ref)
                {
                    fields.Append(MemberIndent)
                        .Append("// ").Append(type)
                        .Append(type.IsArray ? ": row ids in sheet " : ": row id in sheet ")
                        .Append(type.TypeName)
                        .Append('\n');
                }

                fields.Append(MemberIndent)
                    .Append("public ").Append(ToCSharpType(type)).Append(' ').Append(column.Name).Append(';');
            }

            return Render(options.RowClassTemplate, options.Namespace,
                CodeTemplates.ClassNamePlaceholder, className,
                CodeTemplates.FieldsPlaceholder, fields.ToString());
        }

        /// <summary>
        /// Generates an enum with the given members, in the given order, numbered 0, 1, 2…
        /// </summary>
        public static string GenerateEnum(string enumName, IReadOnlyList<string> members, CodeGenOptions options)
        {
            if (members == null)
                throw new ArgumentNullException(nameof(members));

            var numbered = new EnumMember[members.Count];
            for (var i = 0; i < members.Count; i++)
            {
                if (members[i] == null)
                    throw new ArgumentException($"Enum '{enumName}' member at index {i} is null", nameof(members));
                numbered[i] = new EnumMember(members[i], i);
            }
            return GenerateEnum(enumName, numbered, options);
        }

        /// <summary>
        /// Generates an enum with the given members, in the given order, each with its explicit value
        /// (<c>Common = 0,</c>).
        /// </summary>
        public static string GenerateEnum(string enumName, IReadOnlyList<EnumMember> members, CodeGenOptions options)
        {
            ValidateName(enumName, nameof(enumName), "enum name");
            if (members == null)
                throw new ArgumentNullException(nameof(members));
            if (options == null)
                throw new ArgumentNullException(nameof(options));

            var seen = new HashSet<string>(StringComparer.Ordinal);
            var values = new Dictionary<int, string>();
            var text = new StringBuilder();
            for (var i = 0; i < members.Count; i++)
            {
                var member = members[i];
                if (member == null)
                    throw new ArgumentException($"Enum '{enumName}' member at index {i} is null", nameof(members));
                var name = member.Name;
                if (!CSharpIdentifier.IsIdentifier(name))
                    throw new ArgumentException(
                        $"Invalid enum '{enumName}' member '{name}': use Latin letters, digits and '_', not starting with a digit",
                        nameof(members));
                if (CSharpIdentifier.IsKeyword(name))
                    throw new ArgumentException(
                        $"Enum '{enumName}' member '{name}' is a reserved C# keyword", nameof(members));
                if (!seen.Add(name))
                    throw new ArgumentException($"Duplicate enum '{enumName}' member '{name}'", nameof(members));
                if (values.TryGetValue(member.Value, out var other))
                    throw new ArgumentException(
                        $"Duplicate enum '{enumName}' value {member.Value}: members '{other}' and '{name}'", nameof(members));
                values.Add(member.Value, name);

                if (text.Length > 0)
                    text.Append('\n');
                text.Append(MemberIndent).Append(name).Append(" = ")
                    .Append(member.Value.ToString(CultureInfo.InvariantCulture)).Append(',');
            }

            return Render(options.EnumTemplate, options.Namespace,
                CodeTemplates.EnumNamePlaceholder, enumName,
                CodeTemplates.MembersPlaceholder, text.ToString());
        }

        /// <summary>
        /// Reads the members of <c>enum &lt;enumName&gt;</c> from C# source, such as a previously generated file.
        /// Comments are skipped. A member is <c>Name</c> or <c>Name = integer</c>; without a value it is
        /// the previous value + 1, the first one 0 (C# rules). Duplicate names or values,
        /// any other member syntax, or no such enum give an error in the result.
        /// </summary>
        public static EnumReadResult ReadEnumMembers(string source, string enumName)
        {
            if (source == null)
                throw new ArgumentNullException(nameof(source));
            ValidateName(enumName, nameof(enumName), "enum name");

            if (!TryStripCommentsAndStrings(source, out var code, out var stripError))
                return EnumReadResult.Failure(stripError);

            var match = Regex.Match(code,
                @"(?<![A-Za-z0-9_@])enum\s+" + enumName + @"(?![A-Za-z0-9_])\s*(?::\s*[A-Za-z_][A-Za-z0-9_.]*\s*)?\{");
            if (!match.Success)
                return EnumReadResult.Failure($"no 'enum {enumName} {{ ... }}' found");

            var bodyStart = match.Index + match.Length;
            var bodyEnd = code.IndexOf('}', bodyStart);
            if (bodyEnd < 0)
                return EnumReadResult.Failure($"enum '{enumName}' has no closing '}}'");

            var parts = code.Substring(bodyStart, bodyEnd - bodyStart).Split(',');
            var members = new List<EnumMember>();
            var names = new HashSet<string>(StringComparer.Ordinal);
            var values = new Dictionary<int, string>();
            long next = 0;
            for (var i = 0; i < parts.Length; i++)
            {
                var part = parts[i].Trim();
                if (part.Length == 0)
                {
                    // A trailing comma (or an empty enum) is fine; an empty element in the middle is not.
                    if (i == parts.Length - 1)
                        break;
                    return EnumReadResult.Failure($"enum '{enumName}': empty member at position {i + 1}");
                }

                var element = MemberPattern.Match(part);
                if (!element.Success)
                    return EnumReadResult.Failure($"enum '{enumName}': cannot read member '{part}'");

                var name = element.Groups["name"].Value;
                if (CSharpIdentifier.IsKeyword(name))
                    return EnumReadResult.Failure($"enum '{enumName}': member '{name}' is a reserved C# keyword");

                long value;
                if (element.Groups["value"].Success)
                {
                    var digits = Regex.Replace(element.Groups["value"].Value, @"\s+", string.Empty);
                    if (!long.TryParse(digits, NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture, out value) ||
                        value < int.MinValue || value > int.MaxValue)
                        return EnumReadResult.Failure($"enum '{enumName}': value of member '{name}' is out of the int range");
                }
                else
                {
                    value = next;
                    if (value > int.MaxValue)
                        return EnumReadResult.Failure($"enum '{enumName}': value of member '{name}' is out of the int range");
                }

                if (!names.Add(name))
                    return EnumReadResult.Failure($"enum '{enumName}': duplicate member '{name}'");
                var intValue = (int)value;
                if (values.TryGetValue(intValue, out var other))
                    return EnumReadResult.Failure(
                        $"enum '{enumName}': members '{other}' and '{name}' have the same value {intValue}");
                values.Add(intValue, name);

                members.Add(new EnumMember(name, intValue));
                next = value + 1;
            }

            return EnumReadResult.Success(members.AsReadOnly());
        }

        /// <summary>
        /// Keeps the previous members with their values and order, and appends the collected values
        /// that are new, in order of appearance, numbered from the largest previous value + 1 (from 0 when none).
        /// Previous members missing from <paramref name="collected"/> stay and are listed in <see cref="EnumMergeResult.Removed"/>.
        /// </summary>
        public static EnumMergeResult MergeEnumMembers(IReadOnlyList<EnumMember> previous, IReadOnlyList<string> collected)
        {
            if (previous == null)
                throw new ArgumentNullException(nameof(previous));
            if (collected == null)
                throw new ArgumentNullException(nameof(collected));

            var members = new List<EnumMember>();
            var known = new HashSet<string>(StringComparer.Ordinal);
            long max = -1;
            for (var i = 0; i < previous.Count; i++)
            {
                var member = previous[i] ?? throw new ArgumentException($"Previous member at index {i} is null", nameof(previous));
                if (!known.Add(member.Name))
                    throw new ArgumentException($"Duplicate previous member '{member.Name}'", nameof(previous));
                members.Add(member);
                if (member.Value > max)
                    max = member.Value;
            }

            var present = new HashSet<string>(StringComparer.Ordinal);
            for (var i = 0; i < collected.Count; i++)
            {
                var name = collected[i] ?? throw new ArgumentException($"Collected value at index {i} is null", nameof(collected));
                present.Add(name);
                if (!known.Add(name))
                    continue;

                max++;
                if (max > int.MaxValue)
                    throw new ArgumentException($"No free value for new member '{name}': the largest value is {int.MaxValue}",
                        nameof(collected));
                members.Add(new EnumMember(name, (int)max));
            }

            var removed = new List<string>();
            foreach (var member in previous)
            {
                if (!present.Contains(member.Name))
                    removed.Add(member.Name);
            }

            return new EnumMergeResult(members.AsReadOnly(), removed.AsReadOnly());
        }

        private static readonly Regex MemberPattern = new Regex(
            @"^(?<name>[A-Za-z_][A-Za-z0-9_]*)(?:\s*=\s*(?<value>[+-]?\s*[0-9]+))?$", RegexOptions.CultureInvariant);

        // Replaces comments with a space and string/char literal contents with nothing, so that only code is searched.
        private static bool TryStripCommentsAndStrings(string source, out string code, out string error)
        {
            var text = new StringBuilder(source.Length);
            var i = 0;
            while (i < source.Length)
            {
                var c = source[i];
                var next = i + 1 < source.Length ? source[i + 1] : '\0';
                if (c == '/' && next == '/')
                {
                    while (i < source.Length && source[i] != '\n')
                        i++;
                    text.Append(' ');
                }
                else if (c == '/' && next == '*')
                {
                    var end = source.IndexOf("*/", i + 2, StringComparison.Ordinal);
                    if (end < 0)
                    {
                        code = null;
                        error = "unterminated '/*' comment";
                        return false;
                    }
                    i = end + 2;
                    text.Append(' ');
                }
                else if (c == '"' || c == '\'' || (c == '@' && next == '"'))
                {
                    var verbatim = c == '@';
                    var quote = verbatim ? '"' : c;
                    i += verbatim ? 2 : 1;
                    var closed = false;
                    while (i < source.Length)
                    {
                        var s = source[i];
                        if (verbatim && s == '"' && i + 1 < source.Length && source[i + 1] == '"')
                        {
                            i += 2;
                            continue;
                        }
                        if (!verbatim && s == '\\')
                        {
                            i += 2;
                            continue;
                        }
                        if (!verbatim && s == '\n')
                            break;
                        i++;
                        if (s == quote)
                        {
                            closed = true;
                            break;
                        }
                    }
                    if (!closed)
                    {
                        code = null;
                        error = "unterminated string or character literal";
                        return false;
                    }
                    text.Append(quote).Append(quote);
                }
                else
                {
                    text.Append(c);
                    i++;
                }
            }

            code = text.ToString();
            error = null;
            return true;
        }

        /// <summary>
        /// Returns unique enum names used by the columns, in order of first appearance.
        /// </summary>
        public static IReadOnlyList<string> CollectEnumNames(IReadOnlyList<ColumnDefinition> columns)
        {
            if (columns == null)
                throw new ArgumentNullException(nameof(columns));

            var seen = new HashSet<string>(StringComparer.Ordinal);
            var names = new List<string>();
            for (var i = 0; i < columns.Count; i++)
            {
                var column = columns[i];
                if (column == null)
                    throw new ArgumentException($"Column at index {i} is null", nameof(columns));
                if (column.Type.Kind == ColumnKind.Enum && seen.Add(column.Type.TypeName))
                    names.Add(column.Type.TypeName);
            }
            return names.AsReadOnly();
        }

        /// <summary>
        /// Generates the table class of a sheet without <c>ref&lt;X&gt;</c> properties; same as
        /// <see cref="GenerateTableClass(string, string, IReadOnlyList{ColumnDefinition}, CodeGenOptions)"/> with no columns.
        /// </summary>
        public static string GenerateTableClass(string tableClassName, string rowClassName, CodeGenOptions options)
        {
            return GenerateTableClass(tableClassName, rowClassName, Array.Empty<ColumnDefinition>(), options);
        }

        /// <summary>
        /// Generates the table class of a sheet: a <c>SheetTable&lt;&gt;</c> of the row class,
        /// plus the <c>ISheetRow</c> part of the row class (the row class must have a string field <c>id</c>)
        /// with one property per <c>ref&lt;X&gt;</c> column (see <see cref="RefPropertyName"/>), in column order.
        /// The table class of sheet <c>X</c> is assumed to be <c>X</c> + <see cref="TableSuffix"/> in the same namespace.
        /// </summary>
        /// <exception cref="ArgumentException">A name is invalid, or a property name conflicts (see <see cref="FindRefPropertyConflict"/>).</exception>
        public static string GenerateTableClass(string tableClassName, string rowClassName,
            IReadOnlyList<ColumnDefinition> columns, CodeGenOptions options)
        {
            ValidateName(tableClassName, nameof(tableClassName), "table class name");
            ValidateName(rowClassName, nameof(rowClassName), "row class name");
            if (columns == null)
                throw new ArgumentNullException(nameof(columns));
            if (options == null)
                throw new ArgumentNullException(nameof(options));
            if (tableClassName == rowClassName)
                throw new ArgumentException(
                    $"Table class name '{tableClassName}' must differ from the row class name", nameof(tableClassName));

            for (var i = 0; i < columns.Count; i++)
            {
                if (columns[i] == null)
                    throw new ArgumentException($"Column at index {i} is null", nameof(columns));
            }

            var properties = new StringBuilder();
            foreach (var column in columns)
            {
                if (column.Type.Kind != ColumnKind.Ref)
                    continue;

                var conflict = FindRefPropertyConflict(column, columns, rowClassName);
                if (conflict != null)
                    throw new ArgumentException($"Column '{column.Name}': {conflict}", nameof(columns));

                AppendRefProperty(properties, column, options.Namespace);
            }

            return Render(options.TableClassTemplate, options.Namespace,
                CodeTemplates.TableClassNamePlaceholder, tableClassName,
                CodeTemplates.RowClassNamePlaceholder, rowClassName,
                CodeTemplates.RefPropertiesPlaceholder, properties.ToString());
        }

        /// <summary>Suffix of the table class name: sheet <c>Units</c> → <c>UnitsTable</c>.</summary>
        public const string TableSuffix = "Table";

        /// <summary>Private field of the generated row class that holds its table.</summary>
        internal const string TableFieldName = "__table";

        /// <summary>
        /// Name of the property generated for a <c>ref&lt;X&gt;</c> column: the column name with its first letter
        /// in upper case (<c>weapon</c> → <c>Weapon</c>, <c>dropItems</c> → <c>DropItems</c>).
        /// </summary>
        public static string RefPropertyName(string columnName)
        {
            if (columnName == null)
                throw new ArgumentNullException(nameof(columnName));
            if (columnName.Length == 0)
                return columnName;
            return char.ToUpperInvariant(columnName[0]) + columnName.Substring(1);
        }

        /// <summary>
        /// Why the property of a <c>ref&lt;X&gt;</c> column cannot be generated, or <c>null</c> when it can.
        /// The property name must differ from every column name of the sheet (its own column included),
        /// from the row class name and from the private field <c>__table</c>.
        /// </summary>
        public static string FindRefPropertyConflict(ColumnDefinition column, IReadOnlyList<ColumnDefinition> columns,
            string rowClassName)
        {
            var property = RefPropertyName(column.Name);
            var subject = $"property '{property}' generated for {column.Type}";

            foreach (var other in columns)
            {
                if (other != null && other.Name == property)
                    return $"{subject} has the same name as column '{other.Name}'; rename one of the columns";
            }

            if (property == rowClassName)
                return $"{subject} has the same name as the row class '{rowClassName}'; rename the column";
            if (property == TableFieldName)
                return $"{subject} has the same name as the generated field '{TableFieldName}'; rename the column";
            return null;
        }

        private static void AppendRefProperty(StringBuilder text, ColumnDefinition column, string @namespace)
        {
            var type = column.Type;
            var rowType = "global::" + @namespace + "." + type.TypeName;
            var tableType = rowType + TableSuffix;

            text.Append("\n\n").Append(MemberIndent).Append("// ").Append(type);
            if (type.IsArray)
            {
                text.Append(": rows of sheet ").Append(type.TypeName).Append(" by '").Append(column.Name)
                    .Append("'; null items for empty or not found ids, null if the table is not linked\n")
                    .Append(MemberIndent)
                    .Append("public global::System.Collections.Generic.IReadOnlyList<").Append(rowType).Append("> ")
                    .Append(RefPropertyName(column.Name))
                    .Append(" => global::Kentavr.SheetsToSO.SheetRefs.GetMany<");
            }
            else
            {
                text.Append(": row of sheet ").Append(type.TypeName).Append(" by '").Append(column.Name)
                    .Append("'; null if empty, not found or the table is not linked\n")
                    .Append(MemberIndent)
                    .Append("public ").Append(rowType).Append(' ').Append(RefPropertyName(column.Name))
                    .Append(" => global::Kentavr.SheetsToSO.SheetRefs.Get<");
            }

            text.Append(tableType).Append(", ").Append(rowType).Append(">(")
                .Append(TableFieldName).Append(", ").Append(column.Name).Append(");");
        }

        /// <summary>
        /// Collects enum members from the data of <c>enum&lt;X&gt;</c> and <c>enum&lt;X&gt;[]</c> columns:
        /// unique values in order of first appearance (sheets in order, rows top to bottom, columns left to right).
        /// Every enum used by a column is present, with no members when none of its cells has a value.
        /// A value that is not a valid C# name is an error in the result, not an exception.
        /// </summary>
        public static EnumMembersResult CollectEnumMembers(IReadOnlyList<SheetParseResult> sheets)
        {
            if (sheets == null)
                throw new ArgumentNullException(nameof(sheets));

            var names = new List<string>();
            var members = new Dictionary<string, List<string>>(StringComparer.Ordinal);
            var seen = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
            var errors = new List<SheetError>();

            for (var s = 0; s < sheets.Count; s++)
            {
                var sheet = sheets[s];
                if (sheet == null)
                    throw new ArgumentException($"Sheet at index {s} is null", nameof(sheets));

                var enumColumns = new List<ColumnDefinition>();
                foreach (var column in sheet.Columns)
                {
                    if (column.Type.Kind != ColumnKind.Enum)
                        continue;
                    enumColumns.Add(column);
                    var enumName = column.Type.TypeName;
                    if (!members.ContainsKey(enumName))
                    {
                        names.Add(enumName);
                        members.Add(enumName, new List<string>());
                        seen.Add(enumName, new HashSet<string>(StringComparer.Ordinal));
                    }
                }

                if (enumColumns.Count == 0)
                    continue;

                foreach (var row in sheet.Rows)
                {
                    foreach (var column in enumColumns)
                    {
                        if (!row.Values.TryGetValue(column.Name, out var value) || value == null)
                            continue;

                        var address = CellAddress.ToA1(column.ColumnIndex, row.RowNumber);
                        if (value is string[] elements)
                        {
                            for (var i = 0; i < elements.Length; i++)
                                AddEnumMember(sheet.SheetName, column, elements[i], $"element {i + 1} '{elements[i]}'",
                                    address, members, seen, errors);
                        }
                        else if (value is string text)
                        {
                            AddEnumMember(sheet.SheetName, column, text, $"'{text}'", address, members, seen, errors);
                        }
                    }
                }
            }

            var result = new Dictionary<string, IReadOnlyList<string>>(StringComparer.Ordinal);
            foreach (var pair in members)
                result.Add(pair.Key, pair.Value.AsReadOnly());
            return new EnumMembersResult(names.AsReadOnly(), result, errors.AsReadOnly());
        }

        private static void AddEnumMember(string sheetName, ColumnDefinition column, string value, string subject,
            string address, Dictionary<string, List<string>> members, Dictionary<string, HashSet<string>> seen,
            List<SheetError> errors)
        {
            if (string.IsNullOrEmpty(value))
                return;

            var enumName = column.Type.TypeName;
            if (!CSharpIdentifier.IsValidName(value))
            {
                errors.Add(new SheetError(sheetName, new CellError(CellErrorCode.InvalidEnumValue, address,
                    $"Column '{column.Name}': {subject} is not a valid enum '{enumName}' value: " +
                    "use Latin letters, digits and '_', not starting with a digit, and not a C# keyword")));
                return;
            }

            if (seen[enumName].Add(value))
                members[enumName].Add(value);
        }

        private static string ToCSharpType(ColumnType type)
        {
            string baseName;
            switch (type.Kind)
            {
                case ColumnKind.String: baseName = "string"; break;
                case ColumnKind.Int: baseName = "int"; break;
                case ColumnKind.Float: baseName = "float"; break;
                case ColumnKind.Bool: baseName = "bool"; break;
                case ColumnKind.Enum: baseName = type.TypeName; break;
                case ColumnKind.Ref: baseName = "string"; break;
                default: throw new ArgumentOutOfRangeException(nameof(type), type.Kind, "Unknown column kind");
            }
            return type.IsArray ? baseName + "[]" : baseName;
        }

        private static void ValidateName(string value, string paramName, string what)
        {
            if (value == null)
                throw new ArgumentNullException(paramName);
            if (!CSharpIdentifier.IsIdentifier(value))
                throw new ArgumentException(
                    $"Invalid {what} '{value}': use Latin letters, digits and '_', not starting with a digit", paramName);
            if (CSharpIdentifier.IsKeyword(value))
                throw new ArgumentException($"The {what} '{value}' is a reserved C# keyword", paramName);
        }

        private static string Render(string template, string @namespace, params string[] placeholdersAndValues)
        {
            // Templates may come from files with CRLF endings; output is always '\n'.
            var text = template
                .Replace("\r\n", "\n")
                .Replace('\r', '\n')
                .Replace(CodeTemplates.HeaderPlaceholder, Header)
                .Replace(CodeTemplates.NamespacePlaceholder, @namespace);
            for (var i = 0; i < placeholdersAndValues.Length; i += 2)
                text = text.Replace(placeholdersAndValues[i], placeholdersAndValues[i + 1]);
            return text;
        }
    }
}
